CREATE TABLE postgres_schema(version INTEGER PRIMARY KEY);
INSERT INTO postgres_schema VALUES(1);
CREATE TABLE equipment(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL,status TEXT NOT NULL);
CREATE TABLE diagnoses(id TEXT PRIMARY KEY,snapshot TEXT NOT NULL CHECK(snapshot::jsonb IS NOT NULL),created_at TEXT NOT NULL);
CREATE TABLE tickets(id TEXT PRIMARY KEY,equipment_id TEXT NOT NULL REFERENCES equipment(id),diagnosis_id TEXT REFERENCES diagnoses(id),title TEXT NOT NULL,description TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('Open','In Progress','Resolved')),resolution_notes TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,creation_note TEXT NOT NULL,last_note TEXT,last_status_note TEXT);
CREATE TABLE ticket_history(seq BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,ticket_id TEXT NOT NULL REFERENCES tickets(id),version INTEGER NOT NULL,at TEXT NOT NULL,kind TEXT NOT NULL,body TEXT NOT NULL,UNIQUE(ticket_id,version,kind));
CREATE INDEX ticket_history_ticket ON ticket_history(ticket_id,seq);
CREATE INDEX tickets_global_page ON tickets(created_at DESC,id);
CREATE INDEX tickets_equipment_page ON tickets(equipment_id,created_at DESC,id);
CREATE INDEX tickets_diagnosis ON tickets(diagnosis_id);
CREATE TABLE request_budgets(bucket TEXT PRIMARY KEY,used BIGINT NOT NULL CHECK(used>=0));
CREATE TABLE snapshot_manifests(diagnosis_id TEXT PRIMARY KEY REFERENCES diagnoses(id) ON DELETE CASCADE,format TEXT NOT NULL CHECK(format='json-ascii-v1'),schema_version INTEGER NOT NULL CHECK(schema_version=1),byte_length BIGINT NOT NULL CHECK(byte_length>0),chunk_count INTEGER NOT NULL CHECK(chunk_count>0),sha256 TEXT NOT NULL CHECK(length(sha256)=64),created_at TEXT NOT NULL,storage_bytes BIGINT NOT NULL CHECK(storage_bytes>=byte_length),budget_day TEXT NOT NULL,budget_limit BIGINT);
CREATE TABLE snapshot_chunks(diagnosis_id TEXT NOT NULL REFERENCES snapshot_manifests(diagnosis_id) ON DELETE CASCADE,chunk_index INTEGER NOT NULL CHECK(chunk_index>=0),content TEXT NOT NULL CHECK(octet_length(content)<=262144),PRIMARY KEY(diagnosis_id,chunk_index));
CREATE TABLE equipment_ticket_counts(equipment_id TEXT PRIMARY KEY REFERENCES equipment(id) ON DELETE CASCADE,total BIGINT NOT NULL DEFAULT 0);
CREATE FUNCTION equipment_added() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN INSERT INTO equipment_ticket_counts VALUES(NEW.id,0); RETURN NEW; END $$;
CREATE TRIGGER equipment_count_insert AFTER INSERT ON equipment FOR EACH ROW EXECUTE FUNCTION equipment_added();
CREATE FUNCTION ticket_added() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN
 INSERT INTO ticket_history(ticket_id,version,at,kind,body) VALUES(NEW.id,NEW.version,NEW.created_at,'created',NEW.creation_note);
 UPDATE equipment_ticket_counts SET total=total+1 WHERE equipment_id=NEW.equipment_id;
 RETURN NEW;
END $$;
CREATE TRIGGER ticket_created AFTER INSERT ON tickets FOR EACH ROW EXECUTE FUNCTION ticket_added();
CREATE FUNCTION ticket_removed() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN UPDATE equipment_ticket_counts SET total=total-1 WHERE equipment_id=OLD.equipment_id; RETURN OLD; END $$;
CREATE TRIGGER ticket_deleted AFTER DELETE ON tickets FOR EACH ROW EXECUTE FUNCTION ticket_removed();
CREATE FUNCTION ticket_changed() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.version!=OLD.version+1 THEN RAISE EXCEPTION 'invalid_version_step'; END IF;
 IF NEW.last_status_note IS NOT NULL THEN INSERT INTO ticket_history(ticket_id,version,at,kind,body) VALUES(NEW.id,NEW.version,NEW.updated_at,'status',NEW.last_status_note); END IF;
 IF NEW.last_note IS NOT NULL THEN INSERT INTO ticket_history(ticket_id,version,at,kind,body) VALUES(NEW.id,NEW.version,NEW.updated_at,'note',NEW.last_note); END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER ticket_updated AFTER UPDATE OF version ON tickets FOR EACH ROW EXECUTE FUNCTION ticket_changed();
CREATE FUNCTION immutable_evidence() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable_snapshot'; END $$;
CREATE TRIGGER immutable_diagnoses BEFORE UPDATE ON diagnoses FOR EACH ROW EXECUTE FUNCTION immutable_evidence();
CREATE TRIGGER immutable_manifest BEFORE UPDATE ON snapshot_manifests FOR EACH ROW EXECUTE FUNCTION immutable_evidence();
CREATE TRIGGER immutable_chunk BEFORE UPDATE ON snapshot_chunks FOR EACH ROW EXECUTE FUNCTION immutable_evidence();
CREATE FUNCTION guard_manifest() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN
 IF (SELECT snapshot FROM diagnoses WHERE id=NEW.diagnosis_id)!='{"chunked":1}' THEN RAISE EXCEPTION 'snapshot_conflict'; END IF;
 IF EXISTS(SELECT 1 FROM snapshot_manifests WHERE diagnosis_id=NEW.diagnosis_id AND (sha256!=NEW.sha256 OR byte_length!=NEW.byte_length OR chunk_count!=NEW.chunk_count)) THEN RAISE EXCEPTION 'snapshot_conflict'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER manifest_guard BEFORE INSERT ON snapshot_manifests FOR EACH ROW EXECUTE FUNCTION guard_manifest();
CREATE FUNCTION charge_snapshot() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.budget_limit IS NOT NULL THEN
 INSERT INTO request_budgets(bucket,used) VALUES(NEW.budget_day||':snapshot-bytes',NEW.storage_bytes) ON CONFLICT(bucket) DO UPDATE SET used=request_budgets.used+NEW.storage_bytes;
 IF (SELECT used FROM request_budgets WHERE bucket=NEW.budget_day||':snapshot-bytes')>NEW.budget_limit THEN RAISE EXCEPTION 'snapshot_budget'; END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER manifest_budget AFTER INSERT ON snapshot_manifests FOR EACH ROW EXECUTE FUNCTION charge_snapshot();
CREATE FUNCTION guard_chunk() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.chunk_index>=(SELECT chunk_count FROM snapshot_manifests WHERE diagnosis_id=NEW.diagnosis_id) THEN RAISE EXCEPTION 'chunk_index_out_of_range'; END IF;
 IF EXISTS(SELECT 1 FROM snapshot_chunks WHERE diagnosis_id=NEW.diagnosis_id AND chunk_index=NEW.chunk_index AND content!=NEW.content) THEN RAISE EXCEPTION 'immutable_snapshot'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER chunk_guard BEFORE INSERT ON snapshot_chunks FOR EACH ROW EXECUTE FUNCTION guard_chunk();
CREATE FUNCTION guard_manifest_delete() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN
 IF EXISTS(SELECT 1 FROM diagnoses WHERE id=OLD.diagnosis_id) THEN RAISE EXCEPTION 'immutable_snapshot'; END IF; RETURN OLD;
END $$;
CREATE FUNCTION guard_chunk_delete() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN
 IF EXISTS(SELECT 1 FROM snapshot_manifests WHERE diagnosis_id=OLD.diagnosis_id) THEN RAISE EXCEPTION 'immutable_snapshot'; END IF; RETURN OLD;
END $$;
CREATE TRIGGER no_partial_manifest BEFORE DELETE ON snapshot_manifests FOR EACH ROW EXECUTE FUNCTION guard_manifest_delete();
CREATE TRIGGER no_partial_chunk BEFORE DELETE ON snapshot_chunks FOR EACH ROW EXECUTE FUNCTION guard_chunk_delete();
